:root {
  --bg-deep: #0f1b2d;
  --bg-card: #162237;
  --bg-surface: #1e2f47;
  --accent-gold: #f0c040;
  --accent-teal: #4ecdc4;
  --accent-highlight: #7b61ff;
  --text-primary: #e8edf5;
  --text-secondary: #8a9bb8;
  --text-muted: #506080;
  --border-subtle: #2a3f5f;
  --badge-bg: #f0c040;
  --badge-text: #0f1b2d;
  --dot-filled: #4ecdc4;
  --dot-empty: #2a3f5f;
  --highlight-border: #7b61ff;
  --highlight-bg: #201a3d;
}

.planner {
  background-color: var(--bg-deep);
  border-radius: 16px;
  padding: 20px;
  width: 500px;
  max-width: 100%;
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.planner-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.header-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--accent-teal);
  text-transform: uppercase;
  display: block;
  margin-bottom: 4px;
}

.header-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.1;
}

.moon-phase {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.moon-icon {
  font-size: 28px;
  line-height: 1;
}

.moon-label {
  font-size: 10px;
  color: var(--text-secondary);
  font-weight: 600;
  text-align: center;
}

.conditions-bar {
  display: flex;
  justify-content: space-between;
  background-color: var(--bg-surface);
  border-radius: 10px;
  padding: 12px 16px;
  border: 1px solid var(--border-subtle);
}

.condition {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.condition-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-gold);
}

.condition-label {
  font-size: 10px;
  color: var(--text-secondary);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.objects-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.object-card {
  background-color: var(--bg-card);
  border-radius: 10px;
  padding: 12px 10px;
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
  position: relative;
}

.object-card.highlight {
  background-color: var(--highlight-bg);
  border-color: var(--highlight-border);
}

.object-time {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-teal);
  letter-spacing: 0.5px;
}

.object-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.object-info {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.object-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 9px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.planner-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border-subtle);
  padding-top: 12px;
}

.location {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.rating-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rating-label {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.rating-dots {
  display: flex;
  gap: 4px;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--dot-empty);
  display: inline-block;
}

.dot.filled {
  background-color: var(--dot-filled);
}
